-- Migracion del catalogo territorial a INEI 2025
-- Generado por scripts/generar_migracion_distritos.py
-- No editar a mano. Revisar gis/derived/maestro_resumen.txt antes de aplicar.
--
-- Provincias a crear : 126
-- Provincias a ajustar: 70
-- Distritos mantener : 690
-- Distritos borrar   : 8
-- Distritos insertar : 1201

BEGIN;

-- Guarda de idempotencia
CREATE TABLE IF NOT EXISTS core.migracion_log (
    clave text PRIMARY KEY,
    aplicada_en timestamptz NOT NULL DEFAULT now()
);
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM core.migracion_log WHERE clave = 'distritos_inei_2025') THEN
    RAISE EXCEPTION 'migracion distritos_inei_2025 ya aplicada';
  END IF;
END $$;

-- Guarda de estado esperado
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM core.distritos;
  IF n <> 698 THEN
    RAISE EXCEPTION 'se esperaban 698 distritos en la base, hay %', n;
  END IF;
END $$;

-- Respaldo reversible
DROP TABLE IF EXISTS core.distritos_backup_20261123;
CREATE TABLE core.distritos_backup_20261123 AS SELECT * FROM core.distritos;
DROP TABLE IF EXISTS core.provincias_backup_20261123;
CREATE TABLE core.provincias_backup_20261123 AS SELECT * FROM core.provincias;

-- Se relajan las unicidades para poder re-numerar ubigeos en sitio
ALTER TABLE core.distritos DROP CONSTRAINT IF EXISTS distritos_ubigeo_key;
ALTER TABLE core.distritos DROP CONSTRAINT IF EXISTS distritos_provincia_id_nombre_key;
ALTER TABLE core.provincias DROP CONSTRAINT IF EXISTS provincias_ubigeo_key;
ALTER TABLE core.provincias DROP CONSTRAINT IF EXISTS provincias_region_id_nombre_key;

