-- 6) Re-vincular provincia por prefijo de ubigeo
UPDATE core.distritos d SET provincia_id = p.id
FROM core.provincias p
WHERE p.ubigeo = left(d.ubigeo, 4) AND d.provincia_id <> p.id;

