-- Sin resolver por nombre (se dejan como estan):
--   ID_141836: provincia='SATIPO' distrito='MAZAMARI - PANGOA' ubigeo=''
--   ID_100015: provincia='MATARANI' distrito='MATARANI' ubigeo=''

-- 8) Restaurar unicidades
ALTER TABLE core.provincias ADD CONSTRAINT provincias_ubigeo_key UNIQUE (ubigeo);
ALTER TABLE core.provincias ADD CONSTRAINT provincias_region_id_nombre_key UNIQUE (region_id, nombre);
ALTER TABLE core.distritos ADD CONSTRAINT distritos_ubigeo_key UNIQUE (ubigeo);
ALTER TABLE core.distritos ADD CONSTRAINT distritos_provincia_id_nombre_key UNIQUE (provincia_id, nombre);

-- 9) Verificacion final (falla si no cuadra)
DO $$ DECLARE d int; p int; r int; BEGIN
  SELECT count(*) INTO d FROM core.distritos;
  SELECT count(*) INTO p FROM core.provincias;
  SELECT count(*) INTO r FROM core.regiones;
  IF d <> 1891 THEN RAISE EXCEPTION 'distritos: % (esperado 1891)', d; END IF;
  IF p <> 196 THEN RAISE EXCEPTION 'provincias: % (esperado 196)', p; END IF;
  IF r <> 25 THEN RAISE EXCEPTION 'regiones: % (esperado 25)', r; END IF;
END $$;

-- 10) Memoria de abigeos corregidos: distritos con ubigeo distinto al previo
DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM core.distritos d
  JOIN core.distritos_backup_20261123 b ON b.id = d.id
  WHERE b.ubigeo <> d.ubigeo OR b.nombre <> d.nombre;
  RAISE NOTICE 'distritos re-numerados/renombrados: %', n;
END $$;

